/// zs s9/nd8 (`zgc-zs9rv6-wave-s8-review-residuals-FIXED-20261019.md` item 5): the
/// `catch_unwind` panic arms of `cl_define_class_basic` and
/// `define_class_via_full` release every pin they took (the reservation sits
/// above them), as their `Err(msg)` arms do. Before, both returned with their
/// pins still on the stack (`safe_native_call_impl` cut it back later).
#[cfg(test)]
mod zs9nd8_define_panic_pin_tests {
    use super::*;
    use crate::test_utils::{mock_define_full_panics, MockNativeContext};
    #[allow(unused_imports)]
    use cratonvm_native_api::{
        NativeClassAccess, NativeExceptionAccess, NativeHeapAccess, NativeInvokeAccess,
        NativeSystemAccess, NativeThreadAccess,
    };

    /// `public class <name> extends java/lang/Object {}` (version 52).
    fn class_bytes(name: &str) -> Vec<u8> {
        let mut b = vec![0xCA, 0xFE, 0xBA, 0xBE, 0, 0, 0, 52];
        b.extend_from_slice(&5u16.to_be_bytes());
        for (index, text) in [(2u16, name), (4u16, "java/lang/Object")] {
            b.push(7);
            b.extend_from_slice(&index.to_be_bytes());
            b.push(1);
            b.extend_from_slice(&(text.len() as u16).to_be_bytes());
            b.extend_from_slice(text.as_bytes());
        }
        b.extend_from_slice(&0x0021u16.to_be_bytes());
        b.extend_from_slice(&1u16.to_be_bytes());
        b.extend_from_slice(&3u16.to_be_bytes());
        b.extend_from_slice(&[0, 0, 0, 0, 0, 0, 0, 0]);
        b
    }

    fn panicking<T>(f: impl FnOnce() -> T) -> T {
        mock_define_full_panics(true);
        let out = f();
        mock_define_full_panics(false);
        out
    }

    #[test]
    fn zs9nd8_cl_define_class_basic_panic_arm_releases_its_pins() {
        let mut ctx = MockNativeContext::new();
        let cl = ctx.ensure_class_initialized("java/lang/Object").unwrap();
        let this = ctx.alloc_object(cl, 1);
        let bytes = class_bytes("zs9nd8/PanicA");
        let arr = ctx.new_array(cratonvm_types::ArrayElementType::Byte, bytes.len());
        for (i, b) in bytes.iter().enumerate() {
            ctx.set_array_element(arr, i, Value::Int(*b as i8 as i32));
        }
        let before = ctx.native_pin_count_for_test();
        let out = panicking(|| {
            cl_define_class_basic(
                &mut ctx,
                &[
                    Value::Object(Some(this)),
                    Value::Object(None),
                    Value::Object(Some(arr)),
                    Value::Int(0),
                    Value::Int(bytes.len() as i32),
                ],
            )
        });
        assert!(
            out.is_err(),
            "the panic is the define's ClassFormatError: {out:?}"
        );
        assert_eq!(
            ctx.native_pin_count_for_test(),
            before,
            "the panic arm left a pin"
        );
    }

    #[test]
    fn zs9nd8_define_class_via_full_panic_arm_releases_its_pins() {
        let mut ctx = MockNativeContext::new();
        let cl = ctx.ensure_class_initialized("java/lang/Object").unwrap();
        let loader = ctx.alloc_object(cl, 1);
        let data = ctx.alloc_object(cl, 1);
        let before = ctx.native_pin_count_for_test();
        let out = panicking(|| {
            define_class_via_full(
                &mut ctx,
                "zs9nd8/PanicB",
                class_bytes("zs9nd8/PanicB"),
                0,
                cratonvm_native_api::DefineClassFull::default(),
                false,
                Some(Value::Object(Some(data))),
                Value::Object(Some(loader)),
            )
        });
        assert!(
            out.is_err(),
            "the panic is the define's ClassFormatError: {out:?}"
        );
        assert_eq!(
            ctx.native_pin_count_for_test(),
            before,
            "the panic arm left the class-data / loader pins"
        );
    }
}

/// zs s10/nd9 (`zgc-zs9rv6-wave-s8-review-residuals-FIXED-20261019.md` item 4):
/// spent-ladder rows for the `--compatible` definers of this file that had
/// none -- the synthetic `Lookup.defineClass` / `defineHiddenClass` bodies
/// (`lk_define_class`, `lk_define_hidden_class`: registered first, then
/// overwritten by `lookup_define`'s, so reachable only here) and the
/// `URLClassLoader` local define (`ucl_try_define_local_class`). Each row
/// (`test_utils::spent_define_row`): every mirror reservation refused and the
/// reclaim ladder empty -> `OutOfMemoryError`, `define_class_full` never
/// reached, no pin left; then with room the same body defines. Kill control:
/// `CRATONVM_ZGC_DEFINE_MIRROR_RESERVED_EVERY_DEFINER=0` defines first.
#[cfg(test)]
mod zs10nd9_define_rows {
    use super::*;
    use crate::test_utils::{
        assert_kill_row, assert_reserved_row, spent_define_row, MockNativeContext,
    };
    #[allow(unused_imports)]
    use cratonvm_native_api::{
        NativeClassAccess, NativeExceptionAccess, NativeHeapAccess, NativeInvokeAccess,
        NativeSystemAccess, NativeThreadAccess,
    };

    /// `public class <name> extends java/lang/Object {}` (version 52).
    fn class_bytes(name: &str) -> Vec<u8> {
        let mut b = vec![0xCA, 0xFE, 0xBA, 0xBE, 0, 0, 0, 52];
        b.extend_from_slice(&5u16.to_be_bytes());
        for (index, text) in [(2u16, name), (4u16, "java/lang/Object")] {
            b.push(7);
            b.extend_from_slice(&index.to_be_bytes());
            b.push(1);
            b.extend_from_slice(&(text.len() as u16).to_be_bytes());
            b.extend_from_slice(text.as_bytes());
        }
        b.extend_from_slice(&0x0021u16.to_be_bytes());
        b.extend_from_slice(&1u16.to_be_bytes());
        b.extend_from_slice(&3u16.to_be_bytes());
        b.extend_from_slice(&[0, 0, 0, 0, 0, 0, 0, 0]);
        b
    }

    fn byte_array(ctx: &mut MockNativeContext, bytes: &[u8]) -> ObjectRef {
        let arr = ctx.new_array(cratonvm_types::ArrayElementType::Byte, bytes.len());
        for (i, b) in bytes.iter().enumerate() {
            ctx.set_array_element(arr, i, Value::Int(*b as i8 as i32));
        }
        arr
    }

    fn lk_define_class_row(kill: bool) -> crate::test_utils::SpentDefineRow {
        let mut ctx = MockNativeContext::new();
        let lookup = alloc_lookup(&mut ctx, LK_FULL_POWER).unwrap();
        let arr = byte_array(&mut ctx, &class_bytes("zs10nd9/LkDefine"));
        spent_define_row(&mut ctx, kill, |ctx| {
            lk_define_class(
                ctx,
                &[Value::Object(Some(lookup)), Value::Object(Some(arr))],
            )
        })
    }

    #[test]
    fn zs10nd9_lk_define_class_fails_before_it_publishes() {
        assert_reserved_row("lk_define_class", &lk_define_class_row(false));
    }

    #[test]
    fn zs10nd9_lk_define_class_kill_defines_first() {
        assert_kill_row("lk_define_class", &lk_define_class_row(true));
    }

    fn lk_define_hidden_class_row(kill: bool) -> crate::test_utils::SpentDefineRow {
        let mut ctx = MockNativeContext::new();
        let lookup = alloc_lookup(&mut ctx, LK_FULL_POWER).unwrap();
        let arr = byte_array(&mut ctx, &class_bytes("zs10nd9/LkHidden"));
        spent_define_row(&mut ctx, kill, |ctx| {
            lk_define_hidden_class(
                ctx,
                &[
                    Value::Object(Some(lookup)),
                    Value::Object(Some(arr)),
                    Value::Int(0),
                    Value::Object(None),
                ],
            )
        })
    }

    #[test]
    fn zs10nd9_lk_define_hidden_class_fails_before_it_publishes() {
        assert_reserved_row("lk_define_hidden_class", &lk_define_hidden_class_row(false));
    }

    #[test]
    fn zs10nd9_lk_define_hidden_class_kill_defines_first() {
        assert_kill_row("lk_define_hidden_class", &lk_define_hidden_class_row(true));
    }

    /// A synthetic-layout `URLClassLoader` whose one URL is a directory
    /// holding `zs10nd9/<simple>.class`.
    fn ucl_fixture(ctx: &mut MockNativeContext, simple: &str) -> ObjectRef {
        let dir = std::env::temp_dir().join(format!("zs10nd9-ucl-{}-{simple}", std::process::id()));
        let pkg = dir.join("zs10nd9");
        std::fs::create_dir_all(&pkg).expect("temp class dir");
        std::fs::write(
            pkg.join(format!("{simple}.class")),
            class_bytes(&format!("zs10nd9/{simple}")),
        )
        .expect("class file");
        let loader = ctx.alloc_object(cratonvm_types::ClassId::new(1), UCL_FIELD_COUNT);
        let url = ctx.create_string(&dir.to_string_lossy());
        let urls = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 1);
        ctx.set_array_element(urls, 0, Value::Object(Some(url)));
        ctx.set_field(loader, UCL_URLS_ARRAY, Value::Object(Some(urls)));
        ctx.set_field(loader, UCL_URL_COUNT, Value::Int(1));
        loader
    }

    fn ucl_row(kill: bool) -> crate::test_utils::SpentDefineRow {
        let mut ctx = MockNativeContext::new();
        let simple = if kill { "UclK" } else { "Ucl" };
        let loader = ucl_fixture(&mut ctx, simple);
        let name = format!("zs10nd9/{simple}");
        spent_define_row(&mut ctx, kill, |ctx| {
            match ucl_try_define_local_class(ctx, loader, &name) {
                Some(result) => result,
                None => Ok(None),
            }
        })
    }

    #[test]
    fn zs10nd9_ucl_try_define_local_class_fails_before_it_publishes() {
        assert_reserved_row("ucl_try_define_local_class", &ucl_row(false));
    }

    #[test]
    fn zs10nd9_ucl_try_define_local_class_kill_defines_first() {
        assert_kill_row("ucl_try_define_local_class", &ucl_row(true));
    }
}

#[cfg(test)]
mod gci_i4jd_image_app_module_loader_tests {
    use super::*;

    fn fake(addr: usize) -> ObjectRef {
        unsafe { ObjectRef::from_raw(addr as *mut u8) }
    }

    fn seed(vm: usize, adopted: bool) {
        *detached_loader_tables(vm).module_sets.lock() = Some(Arc::new(BuiltinModuleSets {
            boot: ["java.base", "java.desktop"].iter().map(|m| m.to_string()).collect(),
            platform: ["java.sql", "java.compiler"].iter().map(|m| m.to_string()).collect(),
        }));
        with_loader_singletons(detached_loader_tables(vm), |row| {
            row.app = Some(fake(0x4A_D000));
            row.platform = Some(fake(0x4A_E000));
            row.adopted = adopted;
        });
    }

    fn addr(r: Option<ObjectRef>) -> Option<usize> {
        r.map(|r| r.as_ptr() as usize)
    }

    /// An image module in neither of the JDK's boot and platform sets
    /// (`jdk.compiler`) names the adopted application loader; boot and
    /// platform modules do not (the platform ones are the tag arm's).
    #[test]
    fn an_application_image_module_names_the_app_loader() {
        const VM: usize = 0x4A_1000;
        seed(VM, true);
        let t = detached_loader_tables(VM);
        let f = |m: &str, c: &str, on: bool| adopted_app_loader_for_image_module(t, m, c, on);
        assert_eq!(
            addr(f("jdk.compiler", "com/sun/tools/javac/main/JavaCompiler", true)),
            Some(0x4A_D000)
        );
        assert_eq!(addr(f("java.base", "java/lang/String", true)), None);
        assert_eq!(addr(f("java.sql", "java/sql/Connection", true)), None);
        assert_eq!(
            addr(f("jdk.compiler", "com/sun/tools/javac/main/JavaCompiler", false)),
            None
        );
        assert_eq!(addr(f("app.mod", "org/example/Main", true)), None);
        assert_eq!(addr(f("jdk.proxy1", "jdk/proxy1/$Proxy3", true)), None);
        forget_vm_loader_singletons(VM);
    }

    /// Nothing adopted (`--compatible`, or `CRATONVM_REAL_BUILTIN_LOADERS=0`)
    /// or cold module tables: no answer, the mirror keeps today's null.
    #[test]
    fn nothing_adopted_or_cold_tables_answer_none() {
        const VM: usize = 0x4A_2000;
        seed(VM, false);
        assert!(adopted_app_loader_for_image_module(
            detached_loader_tables(VM),
            "jdk.compiler",
            "com/sun/tools/javac/main/JavaCompiler",
            true
        )
        .is_none());
        forget_vm_loader_singletons(VM);
        const COLD: usize = 0x4A_3000;
        with_loader_singletons(detached_loader_tables(COLD), |row| {
            row.app = Some(fake(0x4A_D000));
            row.adopted = true;
        });
        assert!(adopted_app_loader_for_image_module(
            detached_loader_tables(COLD),
            "jdk.compiler",
            "com/sun/tools/javac/main/JavaCompiler",
            true
        )
        .is_none());
        forget_vm_loader_singletons(COLD);
    }
}

/// gci i18/vp: the `Resource.getBytes()[B` intrinsic's decline into the
/// JDK's body is a transparent tail call (`continuation_pin::tail_call`), so
/// a virtual thread whose read of a remote class-path entry parks unmounts,
/// as on HotSpot, instead of being pinned by the intrinsic's native frame.
#[cfg(test)]
mod gci_i18vp_resource_tail_call_tests {
    use super::*;
    use crate::test_utils::MockNativeContext;
    use cratonvm_native_api::continuation_pin::transparent_natives;
    #[allow(unused_imports)]
    use cratonvm_native_api::{
        NativeClassAccess, NativeExceptionAccess, NativeHeapAccess, NativeInvokeAccess,
        NativeSystemAccess, NativeThreadAccess,
    };

    fn gci_i18vp_observe(
        _ctx: &mut MockNativeContext,
        class: &str,
        name: &str,
        desc: &str,
        _args: &[Value],
    ) -> Option<MethodCallResult> {
        (class == JDK_LOADER_RESOURCE && name == "getBytes" && desc == "()[B")
            .then(|| Ok(Some(Value::Int(transparent_natives() as i32))))
    }

    fn gci_i18vp_yield(
        _ctx: &mut MockNativeContext,
        class: &str,
        _name: &str,
        _desc: &str,
        _args: &[Value],
    ) -> Option<MethodCallResult> {
        if class != JDK_LOADER_RESOURCE {
            return None;
        }
        assert_eq!(transparent_natives(), 1);
        Some(Err(MethodCallFailed::InternalError(
            cratonvm_types::error::VmError::ContinuationYield {
                wake_after_nanos: 0,
            },
        )))
    }

    #[test]
    fn gci_i18vp_the_resource_body_is_a_transparent_tail_call() {
        let mut ctx = MockNativeContext::new();
        let resource = ctx.alloc_object(cratonvm_types::ClassId::new(0), 1);
        let args = [Value::Object(Some(resource))];
        ctx.set_invoke_hook(gci_i18vp_observe);
        assert_eq!(resource_get_bytes_body(&mut ctx, &args).ok(), Some(Some(Value::Int(1))));
        assert_eq!(transparent_natives(), 0, "withdrawn after the call");
        ctx.set_invoke_hook(gci_i18vp_yield);
        assert!(matches!(
            resource_get_bytes_body(&mut ctx, &args),
            Err(MethodCallFailed::InternalError(
                cratonvm_types::error::VmError::ContinuationYield { .. }
            ))
        ));
        assert_eq!(transparent_natives(), 0, "withdrawn on the yield too");
    }
}

#[cfg(test)]
mod i100_l3_resource_name_tests {
    use super::{
        chm32_table_len, chm_bucket, is_glob_resource_name, java_string_hash,
        url_names_literal_resource,
    };

    /// Interpreter round i5 wave 100, lane L3: a `*` / `?` resource name is
    /// literal; only a URL that names it exactly survives the filter.
    #[test]
    fn glob_names_keep_only_literal_urls() {
        assert!(is_glob_resource_name("p/*.txt"));
        assert!(is_glob_resource_name("a?b"));
        assert!(!is_glob_resource_name("p/a.txt"));
        assert!(url_names_literal_resource("file:/C:/cp/p/*.txt", "p/*.txt"));
        assert!(url_names_literal_resource("jar:file:/C:/a.jar!/p/*.txt", "p/*.txt"));
        assert!(url_names_literal_resource("file:/cp/*.txt", "*.txt"));
        assert!(!url_names_literal_resource("file:/C:/cp/p/one.txt", "p/*.txt"));
        assert!(!url_names_literal_resource("file:/C:/cp/xp/*.txt", "p/*.txt"));
    }

    /// Wave 99's `module-info.class` order: `String.hashCode`, the
    /// `ConcurrentHashMap<>(32)` table (64 bins, doubled at 48 entries) and
    /// its bin, checked against values computed outside the VM.
    #[test]
    fn chm_bins_follow_the_jdk() {
        assert_eq!(java_string_hash("hello"), 99_162_322);
        assert_eq!(java_string_hash("java.rmi"), -582_849_598);
        assert_eq!(chm32_table_len(0), 64);
        assert_eq!(chm32_table_len(47), 64);
        assert_eq!(chm32_table_len(48), 128);
        assert_eq!(chm_bucket("java.rmi", 64), 0);
        assert_eq!(chm_bucket("jdk.management.jfr", 64), 0);
        assert_eq!(chm_bucket("java.base", 64), 30);
        assert_eq!(chm_bucket("hello", 64), 59);
    }
}

/// JIT round 21 wave 10, lane reflect: `lk_class_relation` against JDK 25's
/// `Lookup.in` (`isSamePackage` / `isSamePackageMember`), for the shapes the
/// old internal-name split got wrong (page
/// `r21-review-w68-native-findings-20261019.md` item 1).
#[cfg(test)]
mod r21_lookup_in_relation_tests {
    use super::*;
    use crate::test_utils::MockNativeContext;
    #[allow(unused_imports)]
    use cratonvm_native_api::{NativeClassAccess, NativeHeapAccess};
    use cratonvm_types::ClassId;

    fn class(ctx: &mut MockNativeContext, name: &str) -> (ClassId, Value) {
        let id = ctx.ensure_class_initialized(name).unwrap();
        let mirror = ctx.get_class_mirror(id);
        (id, Value::Object(Some(mirror)))
    }

    fn rel(ctx: &mut MockNativeContext, a: Value, b: Value) -> (bool, bool, bool) {
        lk_class_relation(ctx, a, b, false).unwrap()
    }

    fn member(ctx: &MockNativeContext, id: ClassId, inner: &str, outer: &str, simple: &str) {
        let entry = (inner.to_string(), outer.to_string(), simple.to_string(), 0);
        ctx.set_inner_classes(id, vec![entry]);
    }

    /// `lookup().in(p.Host.class)` from a lambda's hidden class keeps PACKAGE
    /// (getPackageName cuts `p.Host$$Lambda/0x1a` at its last `.`) and loses
    /// PRIVATE (a hidden class has no InnerClasses link to `Host`): 95 -> 25.
    /// The old split put the hidden class in package `p/Host$$Lambda` (-> 1).
    #[test]
    fn hidden_class_is_in_its_hosts_package_but_not_its_nest() {
        let mut ctx = MockNativeContext::new();
        let (_, host) = class(&mut ctx, "p/Host");
        let (hid, hidden) = class(&mut ctx, "p/Host$$Lambda/0x1a");
        ctx.set_class_hidden(hid);
        assert_eq!(rel(&mut ctx, hidden, host), (false, true, false));
        assert_eq!(rel(&mut ctx, host, hidden), (false, true, false));
        assert_eq!(lk_in_modes(LK_FULL_POWER, false, true, false, true), 25);
    }

    /// A NESTMATE hidden class shares its host's nest, but `Lookup.in` reads
    /// `getEnclosingClass`, never `getNestHost`: still not a package member.
    #[test]
    fn nestmate_hidden_class_still_is_its_own_outermost_class() {
        let mut ctx = MockNativeContext::new();
        let (_, host) = class(&mut ctx, "p/Host");
        let (hid, hidden) = class(&mut ctx, "p/Host/0x2b");
        ctx.set_class_hidden(hid);
        ctx.set_nest_host_override(hid, "p/Host");
        assert_eq!(rel(&mut ctx, hidden, host), (false, true, false));
    }

    /// A member class (its own InnerClasses entry) is a package member of its
    /// top-level class, through any depth; a sibling top-level class is not.
    #[test]
    fn member_classes_share_the_outermost_class() {
        let mut ctx = MockNativeContext::new();
        let (_, a) = class(&mut ctx, "p/A");
        let (bid, _) = class(&mut ctx, "p/A$B");
        member(&ctx, bid, "p/A$B", "p/A", "B");
        let (cid, c) = class(&mut ctx, "p/A$B$C");
        member(&ctx, cid, "p/A$B$C", "p/A$B", "C");
        let (did, d) = class(&mut ctx, "p/A$D");
        member(&ctx, did, "p/A$D", "p/A", "D");
        let (_, other) = class(&mut ctx, "p/Other");
        assert_eq!(rel(&mut ctx, c, a), (false, true, true));
        assert_eq!(rel(&mut ctx, c, d), (false, true, true));
        assert_eq!(rel(&mut ctx, a, other), (false, true, false));
        assert_eq!(rel(&mut ctx, a, a), (true, true, true));
    }

    /// A top-level class whose name holds a `$` is not nested in the class
    /// named by its prefix (the old `$` guess said it was).
    #[test]
    fn dollar_in_a_top_level_name_is_not_nesting() {
        let mut ctx = MockNativeContext::new();
        let (_, odd) = class(&mut ctx, "p/Odd$Name");
        let (_, base) = class(&mut ctx, "p/Odd");
        assert_eq!(rel(&mut ctx, odd, base), (false, true, false));
    }

    /// An enclosing class that is not loaded yet is compared by name (no load,
    /// no GC point); two members of it are still one nest.
    #[test]
    fn unloaded_outer_class_compares_by_name() {
        let mut ctx = MockNativeContext::new();
        let (yid, y) = class(&mut ctx, "p/X$Y");
        member(&ctx, yid, "p/X$Y", "p/X", "Y");
        let (zid, z) = class(&mut ctx, "p/X$Z");
        member(&ctx, zid, "p/X$Z", "p/X", "Z");
        assert_eq!(rel(&mut ctx, y, z), (false, true, true));
        assert!(ctx.class_init_requests().iter().all(|n| n != "p/X"));
    }

    /// A hidden class defined from `p/Outer$Mem` bytes keeps an `InnerClasses`
    /// self entry under its mangled name (the define rewrites it), but
    /// `getDeclaringClass0` refuses that link on HotSpot: it is its own
    /// outermost class, so `in()` with `p/Outer` drops PRIVATE both ways.
    #[test]
    fn hidden_member_bytes_do_not_reach_the_outer_class() {
        let mut ctx = MockNativeContext::new();
        let (_, outer) = class(&mut ctx, "p/Outer");
        let (mid, mem) = class(&mut ctx, "p/Outer$Mem");
        member(&ctx, mid, "p/Outer$Mem", "p/Outer", "Mem");
        let (hid, hidden) = class(&mut ctx, "p/Outer$Mem/0x3c");
        member(&ctx, hid, "p/Outer$Mem/0x3c", "p/Outer", "Mem");
        ctx.set_class_hidden(hid);
        assert_eq!(rel(&mut ctx, hidden, outer), (false, true, false));
        assert_eq!(rel(&mut ctx, outer, hidden), (false, true, false));
        assert_eq!(rel(&mut ctx, hidden, mem), (false, true, false));
        // The non-hidden member class still reaches its outer class.
        assert_eq!(rel(&mut ctx, mem, outer), (false, true, true));
    }

    /// Wave 12, measured on HotSpot 25: while PRIVATE survives, `in()` both
    /// ways between that hidden class and its outer class throws
    /// `getDeclaringClass0`'s IncompatibleClassChangeError. Another package,
    /// or no PRIVATE, does not consult the chain.
    #[test]
    fn hidden_member_bytes_raise_the_declaring_class_icce_when_private_survives() {
        let mut ctx = MockNativeContext::new();
        let (_, outer) = class(&mut ctx, "p/Outer");
        let (hid, hidden) = class(&mut ctx, "p/Outer$Mem/0x3c");
        member(&ctx, hid, "p/Outer$Mem/0x3c", "p/Outer", "Mem");
        ctx.set_class_hidden(hid);
        let (_, other) = class(&mut ctx, "q/Other");
        let expected = "p.Outer and p.Outer$Mem/0x3c disagree on InnerClasses attribute";
        for (a, b) in [(hidden, outer), (outer, hidden)] {
            match lk_class_relation(&mut ctx, a, b, true) {
                Err(MethodCallFailed::InternalError(cratonvm_types::error::VmError::Linkage(
                    cratonvm_types::error::LinkageError::IncompatibleClassChangeError { message },
                ))) => assert_eq!(message, expected),
                other => panic!("expected the ICCE, got {other:?}"),
            }
        }
        assert_eq!(rel(&mut ctx, hidden, outer), (false, true, false));
        let across = lk_class_relation(&mut ctx, hidden, other, true).unwrap();
        assert_eq!(across, (false, false, false));
    }

    /// JIT round 21 wave 14, lane innerclasses
    /// (`CRATONVM_CLASS_INNER_CLASSES_SPOOF_CHECK`; probe
    /// `R21LookupInSpoofedMember`, HotSpot 25): an ORDINARY class that claims
    /// membership in an outer class whose `InnerClasses` does not list it.
    /// While PRIVATE survives, `in()` both ways throws `getDeclaringClass0`'s
    /// ICCE; without PRIVATE the chain is not consulted; a consistent pair
    /// is one nest.
    #[test]
    fn spoofed_ordinary_member_raises_the_icce_when_private_survives() {
        if !cratonvm_types::flags::runtime_flag_default_on("CRATONVM_CLASS_INNER_CLASSES_SPOOF_CHECK")
            || !crate::lang_class::class_inner_classes_check_enabled()
        {
            return;
        }
        let mut ctx = MockNativeContext::new();
        let (_, o1) = class(&mut ctx, "r21spoof/O1");
        let (gid, g1) = class(&mut ctx, "r21spoof/G1");
        member(&ctx, gid, "r21spoof/G1", "r21spoof/O1", "G1");
        let expected = "r21spoof.O1 and r21spoof.G1 disagree on InnerClasses attribute";
        for (a, b) in [(g1, o1), (o1, g1)] {
            match lk_class_relation(&mut ctx, a, b, true) {
                Err(MethodCallFailed::InternalError(cratonvm_types::error::VmError::Linkage(
                    cratonvm_types::error::LinkageError::IncompatibleClassChangeError { message },
                ))) => assert_eq!(message, expected),
                other => panic!("expected the ICCE, got {other:?}"),
            }
        }
        // PRIVATE dropped: no walk error (the link is followed as before).
        assert_eq!(rel(&mut ctx, g1, o1), (false, true, true));
        // The consistent control: the outer class lists the member.
        let (oid2, o2) = class(&mut ctx, "r21spoof/O2");
        let (mid2, m2) = class(&mut ctx, "r21spoof/M2");
        member(&ctx, mid2, "r21spoof/M2", "r21spoof/O2", "M2");
        member(&ctx, oid2, "r21spoof/M2", "r21spoof/O2", "M2");
        assert_eq!(lk_class_relation(&mut ctx, m2, o2, true).unwrap(), (false, true, true));
        assert_eq!(lk_class_relation(&mut ctx, o2, m2, true).unwrap(), (false, true, true));
    }

    /// JIT round 21 wave 16, lane lookup-in (`CRATONVM_LOOKUP_IN_LOADS_OUTER`;
    /// page `r21-review-w10-findings-20261019.md` residual 3R).
    fn loads_outer_on() -> bool {
        cratonvm_types::flags::runtime_flag_default_on("CRATONVM_LOOKUP_IN_LOADS_OUTER")
            && crate::lang_class::class_inner_classes_check_enabled()
    }

    fn expect_icce(result: Result<(bool, bool, bool), MethodCallFailed>, expected: &str) {
        match result {
            Err(MethodCallFailed::InternalError(cratonvm_types::error::VmError::Linkage(
                cratonvm_types::error::LinkageError::IncompatibleClassChangeError { message },
            ))) => assert_eq!(message, expected),
            other => panic!("expected the ICCE, got {other:?}"),
        }
    }

    /// The hidden class from member bytes whose outer class is NOT loaded
    /// yet: the non-loading entry answers PRIVATE-dropped modes without a
    /// load; the rooted entry loads the outer class through the hidden
    /// class's own resolution and throws HotSpot's ICCE, as it does when the
    /// outer class is loaded. The roots come back.
    #[test]
    fn hidden_member_bytes_load_an_unloaded_outer_class_and_raise_the_icce() {
        if !loads_outer_on() {
            return;
        }
        let mut ctx = MockNativeContext::new();
        let (hid, hidden) = class(&mut ctx, "r21lo/Outer$Mem/0x4d");
        member(&ctx, hid, "r21lo/Outer$Mem/0x4d", "r21lo/Outer", "Mem");
        ctx.set_class_hidden(hid);
        let (_, other) = class(&mut ctx, "r21lo/Other");
        assert_eq!(
            lk_class_relation(&mut ctx, hidden, other, true).unwrap(),
            (false, true, false)
        );
        assert!(ctx.class_init_requests().iter().all(|n| n != "r21lo/Outer"));
        let mut roots = [other];
        expect_icce(
            lk_class_relation_rooted(&mut ctx, hidden, other, true, &mut roots),
            "r21lo.Outer and r21lo.Outer$Mem/0x4d disagree on InnerClasses attribute",
        );
        assert!(ctx.class_init_requests().iter().any(|n| n == "r21lo/Outer"));
        assert_eq!(roots[0], other);
    }

    /// An ordinary class claiming membership in an outer class that is not
    /// loaded yet: once loaded, the outer class does not list it, so the
    /// rooted entry throws the spoofed-member ICCE, from either side.
    #[test]
    fn spoofed_member_of_an_unloaded_outer_class_raises_the_icce() {
        if !loads_outer_on()
            || !cratonvm_types::flags::runtime_flag_default_on(
                "CRATONVM_CLASS_INNER_CLASSES_SPOOF_CHECK",
            )
        {
            return;
        }
        let mut ctx = MockNativeContext::new();
        let (gid, g) = class(&mut ctx, "r21ls/G");
        member(&ctx, gid, "r21ls/G", "r21ls/O", "G");
        let (_, x) = class(&mut ctx, "r21ls/X");
        let expected = "r21ls.O and r21ls.G disagree on InnerClasses attribute";
        expect_icce(lk_class_relation_rooted(&mut ctx, g, x, true, &mut []), expected);
        expect_icce(lk_class_relation_rooted(&mut ctx, x, g, true, &mut []), expected);
    }

    /// An outer class that does not exist: the rooted entry throws its
    /// resolution error (`NoClassDefFoundError`, as `getDeclaringClass0`
    /// does). Without PRIVATE the chain is not consulted: no load, no error.
    #[test]
    fn missing_outer_class_is_the_resolution_error() {
        if !loads_outer_on() {
            return;
        }
        let mut ctx = MockNativeContext::new();
        let (mid, m) = class(&mut ctx, "r21lm/Gone$M");
        member(&ctx, mid, "r21lm/Gone$M", "r21lm/Gone", "M");
        let (_, x) = class(&mut ctx, "r21lm/X");
        if !crate::lang_class::outer_resolution_errors_apply(&ctx, mid) {
            return;
        }
        ctx.fail_class_init("r21lm/Gone");
        assert_eq!(
            lk_class_relation_rooted(&mut ctx, m, x, false, &mut []).unwrap(),
            (false, true, false)
        );
        assert!(ctx.class_init_requests().iter().all(|n| n != "r21lm/Gone"));
        match lk_class_relation_rooted(&mut ctx, m, x, true, &mut []) {
            Err(MethodCallFailed::InternalError(cratonvm_types::error::VmError::Linkage(
                cratonvm_types::error::LinkageError::NoClassDefFoundError { class_name },
            ))) => assert_eq!(class_name, "r21lm/Gone"),
            other => panic!("expected the NoClassDefFoundError, got {other:?}"),
        }
    }

    /// `CRATONVM_LOOKUP_IN_LOADS_OUTER=0`: the rooted entry keeps the
    /// by-name answer and loads nothing.
    #[test]
    fn loads_outer_switch_off_keeps_the_by_name_answer() {
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_LOOKUP_IN_LOADS_OUTER", Some("0"))],
            || {
                let mut ctx = MockNativeContext::new();
                let (hid, hidden) = class(&mut ctx, "r21lf/Outer$Mem/0x5e");
                member(&ctx, hid, "r21lf/Outer$Mem/0x5e", "r21lf/Outer", "Mem");
                ctx.set_class_hidden(hid);
                let (_, other) = class(&mut ctx, "r21lf/Other");
                assert_eq!(
                    lk_class_relation_rooted(&mut ctx, hidden, other, true, &mut [])
                        .unwrap(),
                    (false, true, false)
                );
                assert!(ctx.class_init_requests().iter().all(|n| n != "r21lf/Outer"));
            },
        );
    }

    /// `isSamePackage` compares defining loaders first.
    #[test]
    fn same_package_name_of_another_loader_is_another_package() {
        let mut ctx = MockNativeContext::new();
        let (_, a) = class(&mut ctx, "p/A");
        let (bid, b) = class(&mut ctx, "p/B");
        ctx.set_loader_id_override(bid, 5);
        assert_eq!(rel(&mut ctx, a, b), (false, false, false));
    }
}

/// zt t2/nd: [`MemoRows`]' position memo answers what a scan of the rows
/// answers, through every writer shape (append, in-place value change, a
/// shorter `retain`, a same-length rewrite after a generation bump, a clear).
#[cfg(test)]
mod zt2nd_memo_rows_tests {
    use super::*;

    fn obj(addr: usize) -> ObjectRef {
        // Keys only: never dereferenced.
        unsafe { ObjectRef::from_raw(addr as *mut u8) }
    }

    fn scan(rows: &MemoRows<u32>, addr: usize) -> Option<usize> {
        rows.iter().position(|(l, _)| l.as_ptr() as usize == addr)
    }

    fn agree(rows: &mut MemoRows<u32>, generation: u64, addrs: &[usize]) {
        for &a in addrs {
            let want = scan(rows, a);
            assert_eq!(rows.position_of(generation, a, |id| Some(*id)), want, "addr {a:#x}");
        }
    }

    #[test]
    fn zt2nd_the_memo_answers_what_the_scan_answers() {
        let mut rows = MemoRows::<u32>::new();
        let addrs = [0x1000, 0x2000, 0x3000, 0x4000, 0x5000];
        agree(&mut rows, 0, &addrs);
        rows.push((obj(0x1000), 3));
        rows.push((obj(0x2000), 4));
        agree(&mut rows, 0, &addrs);
        // Appended tail, and a duplicate address: the FIRST row wins.
        rows.push((obj(0x3000), 5));
        rows.push((obj(0x1000), 6));
        agree(&mut rows, 0, &addrs);
        assert_eq!(rows.position_of(0, 0x1000, |id| Some(*id)), Some(0));
        // A value changed in place keeps its position.
        rows[1].1 = 9;
        agree(&mut rows, 0, &addrs);
        // A shorter `retain` (a test helper's) rebuilds.
        rows.retain(|(_, id)| *id != 3);
        agree(&mut rows, 0, &addrs);
        // The GC pass remaps keys in place (same length) AFTER bumping the
        // generation: the memo rebuilds.
        for (l, _) in rows.iter_mut() {
            *l = obj(l.as_ptr() as usize + 0x10_0000);
        }
        let moved: Vec<usize> = addrs.iter().map(|a| a + 0x10_0000).collect();
        agree(&mut rows, 1, &moved);
        agree(&mut rows, 1, &addrs);
        // A clear, then the same length again in the same generation.
        rows.clear_rows();
        rows.push((obj(0x4000), 7));
        rows.push((obj(0x5000), 8));
        rows.push((obj(0x2000), 10));
        agree(&mut rows, 1, &addrs);
    }

    #[test]
    fn zt2nd_the_id_memo_finds_the_first_row_of_an_id() {
        let mut rows = MemoRows::<u32>::new();
        rows.push((obj(0x1000), 3));
        rows.push((obj(0x2000), 4));
        rows.push((obj(0x3000), 4));
        rows.sync(0, |id| Some(*id));
        assert_eq!(rows.memo.by_key.get(&4).copied(), Some(1));
        assert!(row_has_id(&rows, 1, 4));
        assert!(!row_has_id(&rows, 0, 4));
        assert!(row_has_loader(&rows, 2, 0x3000));
        assert!(!row_has_loader(&rows, 5, 0x3000));
    }
}

/// zt t3/x2: the reconcile's rewrite drops the [`MemoRows`] memo under the
/// table's lock (`retain_rows_mut`). A lookup between the generation bump and
/// the rewrite rebuilds the memo at the new generation from the old rows; a
/// same-length remap of a non-last row then passes every staleness check.
#[cfg(test)]
mod zt3x2_memo_rows_reconcile_window_tests {
    use super::*;

    fn obj(addr: usize) -> ObjectRef {
        // SAFETY: a key only, never dereferenced.
        unsafe { ObjectRef::from_raw(addr as *mut u8) }
    }

    /// Three rows, and a lookup at generation 1 (the reconcile's bump has
    /// happened, its rewrite has not).
    fn rows_seen_in_the_window() -> MemoRows<u32> {
        let mut rows = MemoRows::<u32>::new();
        rows.push((obj(0x1000), 1));
        rows.push((obj(0x2000), 2));
        rows.push((obj(0x3000), 3));
        assert_eq!(rows.position_of(1, 0x1000, |id| Some(*id)), Some(0));
        rows
    }

    /// The remap the reconcile applies: the FIRST row's loader moved, the
    /// last one did not (same length, same last address).
    fn remap(row: &mut (ObjectRef, u32)) -> bool {
        if row.0.as_ptr() as usize == 0x1000 {
            row.0 = obj(0x9000);
        }
        true
    }

    #[test]
    fn zt3x2_a_remap_after_a_lookup_in_the_window_is_found() {
        let mut rows = rows_seen_in_the_window();
        rows.retain_rows_mut(remap);
        assert_eq!(rows.position_of(1, 0x9000, |id| Some(*id)), Some(0));
        assert_eq!(rows.position_of(1, 0x1000, |id| Some(*id)), None);
    }

    /// The positive control: the same remap through the plain `Vec` (the t2
    /// shape of the reconcile) leaves the memo answering the old address and
    /// missing the new one, which a scan finds.
    #[test]
    fn zt3x2_control_a_plain_retain_leaves_the_memo_stale() {
        let mut rows = rows_seen_in_the_window();
        rows.retain_mut(remap);
        assert_eq!(rows.iter().position(|(l, _)| l.as_ptr() as usize == 0x9000), Some(0));
        assert_eq!(rows.position_of(1, 0x9000, |id| Some(*id)), None, "the stale miss");
    }
}

/// zt t6/nd4: the `classes` presize ahead of the define
/// ([`presize_loader_classes`], zt1nd page item 1).
#[cfg(test)]
mod zt6nd4_addclass_presize_tests {
    use super::*;
    use crate::test_utils::MockNativeContext;
    #[allow(unused_imports)]
    use cratonvm_native_api::{
        NativeClassAccess, NativeExceptionAccess, NativeGpuAccess, NativeHeapAccess,
        NativeInvokeAccess, NativeSystemAccess, NativeThreadAccess,
    };

    /// The lists' element component (any id but the untyped `0`).
    fn element_component() -> cratonvm_types::ClassId {
        cratonvm_types::ClassId::new(1)
    }

    thread_local! {
        static ADDS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
    }

    fn declare(ctx: &mut MockNativeContext, class_name: &str, names: &[&str]) {
        let cid = ctx.ensure_class_initialized(class_name).expect("class");
        let fields = names
            .iter()
            .enumerate()
            .map(|(i, n)| cratonvm_native_api::FieldMetadata {
                name: (*n).to_string(),
                descriptor: "Ljava/lang/Object;".to_string(),
                access_flags: 0,
                slot_index: i,
                declaring_class_id: cid,
                is_static: false,
            })
            .collect();
        ctx.set_declared_fields(cid, fields);
    }

    fn object(ctx: &mut MockNativeContext, class_name: &str) -> ObjectRef {
        match ctx.new_object(class_name).unwrap() {
            Some(Value::Object(Some(obj))) => obj,
            other => panic!("expected {class_name} object, got {other:?}"),
        }
    }

    /// A loader whose `classes` list holds `size` elements in an
    /// `elementData` of `capacity` slots. zt t7/x4: the classes are the JDK's
    /// own names, `java/lang/ClassLoader` (whose `classes` slot the presize
    /// resolves) and `java/util/ArrayList` (the only list class it touches).
    fn loader_with_list(
        ctx: &mut MockNativeContext,
        size: usize,
        capacity: usize,
    ) -> (ObjectRef, ObjectRef) {
        declare(ctx, CL_CLASS, &["classes"]);
        let loader = object(ctx, CL_CLASS);
        let list = list_of(ctx, ARRAY_LIST_CLASS, size, capacity);
        ctx.set_field_by_name(loader, "classes", Value::Object(Some(list)));
        ADDS.with(|c| c.set(0));
        (loader, list)
    }

    /// A list object of `class_name` with `size` elements in an
    /// `elementData` of `capacity` slots.
    fn list_of(
        ctx: &mut MockNativeContext,
        class_name: &str,
        size: usize,
        capacity: usize,
    ) -> ObjectRef {
        declare(ctx, class_name, &["elementData", "size"]);
        let list = object(ctx, class_name);
        let data = ctx.new_ref_array(element_component(), capacity);
        for i in 0..size {
            let element = object(ctx, "example/Zt6Nd4Element");
            ctx.set_array_element(data, i, Value::Object(Some(element)));
        }
        ctx.set_field_by_name(list, "elementData", Value::Object(Some(data)));
        ctx.set_field_by_name(list, "size", Value::Int(size as i32));
        list
    }

    /// `ArrayList.add(Object)`: grow by the JDK's policy when full, store,
    /// bump `size`.
    fn array_list_add(
        ctx: &mut MockNativeContext,
        receiver: ObjectRef,
        method_name: &str,
        descriptor: &str,
        args: &[Value],
    ) -> Option<MethodCallResult> {
        if method_name != "add" || descriptor != "(Ljava/lang/Object;)Z" {
            return None;
        }
        ADDS.with(|c| c.set(c.get() + 1));
        let size = match ctx.get_field_by_name(receiver, "size") {
            Value::Int(n) => n as usize,
            _ => 0,
        };
        let old = match ctx.get_field_by_name(receiver, "elementData") {
            Value::Object(Some(a)) => a,
            other => panic!("elementData: {other:?}"),
        };
        let capacity = ctx.array_length(old);
        let data = if size == capacity {
            let grown =
                ctx.new_ref_array(element_component(), (capacity + (capacity >> 1)).max(10));
            for i in 0..size {
                let v = ctx.get_array_element(old, i);
                ctx.set_array_element(grown, i, v);
            }
            ctx.set_field_by_name(receiver, "elementData", Value::Object(Some(grown)));
            grown
        } else {
            old
        };
        ctx.set_array_element(data, size, args[0]);
        ctx.set_field_by_name(receiver, "size", Value::Int(size as i32 + 1));
        Some(Ok(Some(Value::Int(1))))
    }

    /// `ArrayList.add(Object)` on a spent heap: the growth throws.
    fn array_list_add_refused(
        _ctx: &mut MockNativeContext,
        _receiver: ObjectRef,
        method_name: &str,
        _descriptor: &str,
        _args: &[Value],
    ) -> Option<MethodCallResult> {
        if method_name != "add" {
            return None;
        }
        ADDS.with(|c| c.set(c.get() + 1));
        Some(Err(crate::util_concurrent_ext::native_heap_oom(
            "java.lang.Object[]",
        )))
    }

    fn capacity_of(ctx: &MockNativeContext, list: ObjectRef) -> usize {
        match ctx.get_field_by_name(list, "elementData") {
            Value::Object(Some(a)) => ctx.array_length(a),
            other => panic!("elementData: {other:?}"),
        }
    }

    #[test]
    fn zt6nd4_a_full_list_grows_before_the_define_and_keeps_its_contents() {
        let mut ctx = MockNativeContext::new();
        let (loader, list) = loader_with_list(&mut ctx, 10, 10);
        ctx.set_invoke_virtual_hook(array_list_add);
        assert!(array_list_is_full(&ctx, list));

        presize_loader_classes(&mut ctx, loader).expect("presize");

        assert_eq!(ADDS.with(std::cell::Cell::get), 1, "one add, the growth");
        assert_eq!(
            ctx.get_field_by_name(list, "size"),
            Value::Int(10),
            "contents unchanged"
        );
        assert_eq!(
            capacity_of(&ctx, list),
            15,
            "the capacity addClass's own add would reach"
        );
        assert!(
            !array_list_is_full(&ctx, list),
            "addClass now has a free slot"
        );
        assert_eq!(ctx.monitor_depth.get(), 0, "the monitor is released");
    }

    /// The empty default list (`elementData` of length 0) is full too: its
    /// first `add` allocates the 10-slot array.
    #[test]
    fn zt6nd4_the_empty_default_list_gets_its_first_array_before_the_define() {
        let mut ctx = MockNativeContext::new();
        let (loader, list) = loader_with_list(&mut ctx, 0, 0);
        ctx.set_invoke_virtual_hook(array_list_add);

        presize_loader_classes(&mut ctx, loader).expect("presize");

        assert_eq!(ADDS.with(std::cell::Cell::get), 1);
        assert_eq!(ctx.get_field_by_name(list, "size"), Value::Int(0));
        assert_eq!(capacity_of(&ctx, list), 10);
    }

    #[test]
    fn zt6nd4_a_list_with_room_is_left_alone() {
        let mut ctx = MockNativeContext::new();
        let (loader, list) = loader_with_list(&mut ctx, 3, 10);
        ctx.set_invoke_virtual_hook(array_list_add);

        presize_loader_classes(&mut ctx, loader).expect("presize");

        assert_eq!(ADDS.with(std::cell::Cell::get), 0, "no Java call, no monitor");
        assert_eq!(ctx.get_field_by_name(list, "size"), Value::Int(3));
        assert_eq!(capacity_of(&ctx, list), 10);
        assert_eq!(ctx.monitor_depth.get(), 0);
    }

    /// The refusal is the define's `OutOfMemoryError`, raised before the
    /// reservation, with the monitor released.
    #[test]
    fn zt6nd4_a_refused_growth_is_the_defines_error_and_releases_the_monitor() {
        let mut ctx = MockNativeContext::new();
        let (loader, list) = loader_with_list(&mut ctx, 10, 10);
        ctx.set_invoke_virtual_hook(array_list_add_refused);

        let err = presize_loader_classes(&mut ctx, loader).expect_err("refused growth");

        assert!(format!("{err:?}").contains("OutOfMemoryError"), "{err:?}");
        assert_eq!(ADDS.with(std::cell::Cell::get), 1);
        assert_eq!(ctx.get_field_by_name(list, "size"), Value::Int(10));
        assert_eq!(
            ctx.monitor_depth.get(),
            0,
            "the monitor is released on the error arm"
        );
    }

    /// A loader without the JDK's `classes` list (our synthetic layout) is
    /// left alone.
    #[test]
    fn zt6nd4_a_loader_without_a_classes_list_is_left_alone() {
        let mut ctx = MockNativeContext::new();
        declare(&mut ctx, "example/Zt6Nd4Bare", &["parent"]);
        let loader = object(&mut ctx, "example/Zt6Nd4Bare");
        ctx.set_invoke_virtual_hook(array_list_add);
        ADDS.with(|c| c.set(0));

        presize_loader_classes(&mut ctx, loader).expect("presize");

        assert_eq!(ADDS.with(std::cell::Cell::get), 0);
    }

    /// zt t7/x4 (finding 1): a user loader that declares its OWN `classes`
    /// field (an `ArrayList`, full) shadows `ClassLoader.classes` for a
    /// by-name read. The presize grows the JDK's list (the slot `addClass`
    /// uses) and leaves the user's list alone: no `add`, no capacity change.
    /// Before the fix the by-name read answered the user's list, so the
    /// assertions on both lists fail.
    #[test]
    fn zt7x4_a_user_loaders_own_classes_field_is_left_alone() {
        let mut ctx = MockNativeContext::new();
        // `ClassLoader.classes` at slot 0; the subclass re-declares `classes`
        // at slot 2 (the object carries both, as an inherited layout does).
        // gcj j2/x1: both layouts carry `nameAndId`, a real-`ClassLoader`
        // witness (`REAL_CLASSLOADER_WITNESS_FIELDS`). Keep `parallelLockMap`
        // as the inherited-layout witness too. Without these witnesses the loader
        // reads as the synthetic layout, `loader_classes_list` takes the
        // by-name read (the synthetic layout has no declared slot to prefer)
        // and the test failed on the fixture, not on the code.
        declare(&mut ctx, CL_CLASS, &["classes", "parallelLockMap", "nameAndId"]);
        declare(
            &mut ctx,
            "example/Zt7X4UserLoader",
            &["classes$jdk", "parallelLockMap", "nameAndId", "classes"],
        );
        let loader = object(&mut ctx, "example/Zt7X4UserLoader");
        assert!(
            !cl_has_synthetic_layout(&ctx, loader),
            "fixture: the real ClassLoader layout"
        );
        let jdk_list = list_of(&mut ctx, ARRAY_LIST_CLASS, 10, 10);
        let user_list = list_of(&mut ctx, ARRAY_LIST_CLASS, 10, 10);
        let jdk_slot = ctx.resolve_field_index(CL_CLASS, "classes").expect("slot");
        ctx.set_field(loader, jdk_slot, Value::Object(Some(jdk_list)));
        ctx.set_field_by_name(loader, "classes", Value::Object(Some(user_list)));
        assert_eq!(
            ctx.get_field_by_name(loader, "classes"),
            Value::Object(Some(user_list)),
            "fixture: the by-name read answers the subclass's shadow"
        );
        ADDS.with(|c| c.set(0));
        ctx.set_invoke_virtual_hook(array_list_add);

        presize_loader_classes(&mut ctx, loader).expect("presize");

        assert_eq!(ADDS.with(std::cell::Cell::get), 1, "one add");
        assert_eq!(capacity_of(&ctx, jdk_list), 15, "the JDK's list grew");
        assert_eq!(capacity_of(&ctx, user_list), 10, "the user's list is untouched");
        assert_eq!(ctx.get_field_by_name(user_list, "size"), Value::Int(10));
        assert_eq!(ctx.monitor_depth.get(), 0);
    }

    /// zt t7/x4 (finding 1): a full list that is not exactly a
    /// `java.util.ArrayList` (a subclass may override `add` or re-declare
    /// `size`) is not touched; the exact class (the control) is.
    #[test]
    fn zt7x4_only_an_exact_array_list_is_presized() {
        let mut ctx = MockNativeContext::new();
        let (loader, _) = loader_with_list(&mut ctx, 10, 10);
        let sub = list_of(&mut ctx, "example/Zt7X4ArrayListSubclass", 10, 10);
        ctx.set_field_by_name(loader, "classes", Value::Object(Some(sub)));
        ctx.set_invoke_virtual_hook(array_list_add);
        assert!(!array_list_is_full(&ctx, sub), "not an ArrayList: never full");

        presize_loader_classes(&mut ctx, loader).expect("presize");

        assert_eq!(ADDS.with(std::cell::Cell::get), 0, "no Java call");
        assert_eq!(capacity_of(&ctx, sub), 10);
        let exact = list_of(&mut ctx, ARRAY_LIST_CLASS, 10, 10);
        assert!(array_list_is_full(&ctx, exact), "control: the exact class");
    }

    /// The order the fix rests on: in `define_class_via_full` the presize
    /// comes before the mirror reservation (and so before the define), and
    /// `record_with_loader` (the `addClass` call) after the define.
    #[test]
    fn zt6nd4_the_presize_runs_before_the_reservation_in_the_definer() {
        let src = include_str!("classloader.rs");
        let start = src
            .find("pub(crate) fn define_class_via_full(")
            .expect("definer");
        let end = start
            + src[start..]
                .find("\nfn record_with_loader(")
                .expect("record_with_loader after the definer");
        let body = &src[start..end];
        let presize = body.find("presize_loader_classes(ctx").expect("presize call");
        let reserve = body.find("reserve_mirror_for_define(").expect("reservation");
        let define = body.find("ctx.define_class_full(").expect("define");
        let add = body.find("record_with_loader(ctx").expect("addClass");
        assert!(presize < reserve, "the presize must precede the reservation");
        assert!(reserve < define && define < add);
    }
}

/// zt t7/cl: the `ClassLoader.addClass` upcall of the real-JDK define doors
/// ([`add_defined_class_to_loader`], t6/nd4 finding 14) and their ZGC presize
/// ([`presize_for_add_class`]).
#[cfg(test)]
mod zt7cl_add_class_tests {
    use super::*;
    use crate::test_utils::{mock_heap_is_zgc, mock_method_exists, MockNativeContext};
    #[allow(unused_imports)]
    use cratonvm_native_api::{
        NativeClassAccess, NativeExceptionAccess, NativeGpuAccess, NativeHeapAccess,
        NativeInvokeAccess, NativeSystemAccess, NativeThreadAccess,
    };

    thread_local! {
        /// `(receiver class id, argument address)` of each `addClass` call.
        static ADD_CLASS_CALLS: std::cell::RefCell<Vec<(u32, usize)>> =
            const { std::cell::RefCell::new(Vec::new()) };
        /// `ArrayList.add` calls (the presize's growth).
        static LIST_ADDS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
    }

    fn calls() -> Vec<(u32, usize)> {
        ADD_CLASS_CALLS.with(|c| c.borrow().clone())
    }

    fn declare(ctx: &mut MockNativeContext, class_name: &str, names: &[&str]) {
        let cid = ctx.ensure_class_initialized(class_name).expect("class");
        let fields = names
            .iter()
            .enumerate()
            .map(|(i, n)| cratonvm_native_api::FieldMetadata {
                name: (*n).to_string(),
                descriptor: "Ljava/lang/Object;".to_string(),
                access_flags: 0,
                slot_index: i,
                declaring_class_id: cid,
                is_static: false,
            })
            .collect();
        ctx.set_declared_fields(cid, fields);
    }

    fn object(ctx: &mut MockNativeContext, class_name: &str) -> ObjectRef {
        match ctx.new_object(class_name).unwrap() {
            Some(Value::Object(Some(obj))) => obj,
            other => panic!("expected {class_name} object, got {other:?}"),
        }
    }

    /// A loader on the REAL `ClassLoader` layout (a witness field declared),
    /// its `classes` list holding `size` of `capacity` slots (`None`: the
    /// field is null), and a stand-in mirror. `addClass` exists.
    fn fixture(
        ctx: &mut MockNativeContext,
        list: Option<(usize, usize)>,
    ) -> (ObjectRef, ObjectRef) {
        declare(ctx, CL_CLASS, &["classes", "nameAndId"]);
        declare(ctx, "java/util/ArrayList", &["elementData", "size"]);
        let loader = object(ctx, CL_CLASS);
        if let Some((size, capacity)) = list {
            let classes = object(ctx, "java/util/ArrayList");
            let data = ctx.new_ref_array(cratonvm_types::ClassId::new(1), capacity);
            for i in 0..size {
                let element = object(ctx, "example/Zt7ClElement");
                ctx.set_array_element(data, i, Value::Object(Some(element)));
            }
            ctx.set_field_by_name(classes, "elementData", Value::Object(Some(data)));
            ctx.set_field_by_name(classes, "size", Value::Int(size as i32));
            ctx.set_field_by_name(loader, "classes", Value::Object(Some(classes)));
        }
        let mirror = object(ctx, "example/Zt7ClMirror");
        mock_method_exists(CL_CLASS, "addClass", ADD_CLASS_DESCRIPTOR);
        ADD_CLASS_CALLS.with(|c| c.borrow_mut().clear());
        LIST_ADDS.with(|c| c.set(0));
        (loader, mirror)
    }

    /// `addClass` records its call; `ArrayList.add` grows the list (10, then
    /// 1.5x) and stores.
    fn hook(
        ctx: &mut MockNativeContext,
        receiver: ObjectRef,
        method_name: &str,
        descriptor: &str,
        args: &[Value],
    ) -> Option<MethodCallResult> {
        match (method_name, descriptor) {
            ("addClass", ADD_CLASS_DESCRIPTOR) => {
                let arg = match args.first() {
                    Some(Value::Object(Some(m))) => m.as_ptr() as usize,
                    _ => 0,
                };
                let cid = ctx.class_id_of_object(receiver).as_u32();
                ADD_CLASS_CALLS.with(|c| c.borrow_mut().push((cid, arg)));
                Some(Ok(None))
            }
            ("add", "(Ljava/lang/Object;)Z") => {
                LIST_ADDS.with(|c| c.set(c.get() + 1));
                let size = match ctx.get_field_by_name(receiver, "size") {
                    Value::Int(n) => n as usize,
                    _ => 0,
                };
                let old = match ctx.get_field_by_name(receiver, "elementData") {
                    Value::Object(Some(a)) => a,
                    other => panic!("elementData: {other:?}"),
                };
                let capacity = ctx.array_length(old);
                let data = if size == capacity {
                    let grown = ctx.new_ref_array(
                        cratonvm_types::ClassId::new(1),
                        (capacity + (capacity >> 1)).max(10),
                    );
                    for i in 0..size {
                        let v = ctx.get_array_element(old, i);
                        ctx.set_array_element(grown, i, v);
                    }
                    ctx.set_field_by_name(receiver, "elementData", Value::Object(Some(grown)));
                    grown
                } else {
                    old
                };
                ctx.set_array_element(data, size, args[0]);
                ctx.set_field_by_name(receiver, "size", Value::Int(size as i32 + 1));
                Some(Ok(Some(Value::Int(1))))
            }
            _ => None,
        }
    }

    /// `addClass` on a spent heap: the growth throws.
    fn refusing_hook(
        _ctx: &mut MockNativeContext,
        _receiver: ObjectRef,
        method_name: &str,
        _descriptor: &str,
        _args: &[Value],
    ) -> Option<MethodCallResult> {
        if method_name != "addClass" {
            return None;
        }
        Some(Err(crate::util_concurrent_ext::native_heap_oom(
            "java.lang.Object[]",
        )))
    }

    #[test]
    fn zt7cl_the_defined_class_is_added_to_its_loaders_list() {
        let mut ctx = MockNativeContext::new();
        let (loader, mirror) = fixture(&mut ctx, Some((0, 0)));
        ctx.set_invoke_virtual_hook(hook);
        let loader_cid = ctx.class_id_of_object(loader).as_u32();

        let out = add_defined_class_to_loader(&mut ctx, loader, mirror).expect("addClass");

        assert_eq!(out, mirror, "a non-moving heap: the same mirror back");
        assert_eq!(
            calls(),
            vec![(loader_cid, mirror.as_ptr() as usize)],
            "one addClass, on the loader, with the mirror"
        );
        assert_eq!(ctx.native_pin_count_for_test(), 0, "the mirror pin is released");
    }

    /// The upcall is a GC point: the mirror handed back is the one the call
    /// saw, re-read through its pin (the input address is retired).
    #[test]
    fn zt7cl_the_mirror_is_reread_across_the_upcall() {
        let mut ctx = MockNativeContext::new();
        let (loader, mirror) = fixture(&mut ctx, Some((0, 0)));
        ctx.set_invoke_virtual_hook(hook);
        ctx.set_moving_heap_vm_rule(true);

        let out = add_defined_class_to_loader(&mut ctx, loader, mirror).expect("addClass");

        let seen = calls();
        assert_eq!(seen.len(), 1);
        assert_eq!(
            out.as_ptr() as usize,
            seen[0].1,
            "the returned mirror is the forwarded one the upcall stored"
        );
        let _ = ctx.class_id_of_object(out); // panics on a retired address
    }

    /// Kill arm: `CRATONVM_DEFINE_ADD_CLASS=0` makes no upcall.
    #[test]
    fn zt7cl_the_kill_switch_makes_no_upcall() {
        let mut ctx = MockNativeContext::new();
        let (loader, mirror) = fixture(&mut ctx, Some((0, 0)));
        ctx.set_invoke_virtual_hook(hook);
        let _off = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                "CRATONVM_DEFINE_ADD_CLASS",
                Some("0"),
            )]),
        );

        let out = add_defined_class_to_loader(&mut ctx, loader, mirror).expect("no call");

        assert_eq!(out, mirror);
        assert!(calls().is_empty(), "no addClass with the switch off");
    }

    /// A loader whose `classes` is null (a VM-made loader object) is left
    /// alone: `addClass` would throw `NullPointerException` there.
    #[test]
    fn zt7cl_a_loader_without_a_list_makes_no_upcall() {
        let mut ctx = MockNativeContext::new();
        let (loader, mirror) = fixture(&mut ctx, None);
        ctx.set_invoke_virtual_hook(hook);

        add_defined_class_to_loader(&mut ctx, loader, mirror).expect("no call");

        assert!(calls().is_empty());
    }

    /// The upcall's `OutOfMemoryError` is the define's (HotSpot propagates
    /// `addClass`'s exception), with the pin released.
    #[test]
    fn zt7cl_a_refused_upcall_is_the_defines_error() {
        let mut ctx = MockNativeContext::new();
        let (loader, mirror) = fixture(&mut ctx, Some((0, 0)));
        ctx.set_invoke_virtual_hook(refusing_hook);

        let err = add_defined_class_to_loader(&mut ctx, loader, mirror).expect_err("refused");

        assert!(format!("{err:?}").contains("OutOfMemoryError"), "{err:?}");
        assert_eq!(ctx.native_pin_count_for_test(), 0);
    }

    /// The ZGC presize for these doors: a full list grows before the define
    /// on ZGC only, and not with the upcall killed; the boot loader (`None`)
    /// is left alone.
    #[test]
    fn zt7cl_the_presize_is_zgc_only_and_follows_the_upcall_switch() {
        let mut ctx = MockNativeContext::new();
        let (loader, _) = fixture(&mut ctx, Some((10, 10)));
        ctx.set_invoke_virtual_hook(hook);

        mock_heap_is_zgc(false);
        presize_for_add_class(&mut ctx, Some(loader)).expect("off ZGC");
        assert_eq!(LIST_ADDS.with(std::cell::Cell::get), 0, "G1 / Generational: no presize");

        mock_heap_is_zgc(true);
        presize_for_add_class(&mut ctx, None).expect("boot loader");
        assert_eq!(LIST_ADDS.with(std::cell::Cell::get), 0, "no loader object: nothing");
        {
            let _off = cratonvm_types::flags::override_thread(
                cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                    "CRATONVM_DEFINE_ADD_CLASS",
                    Some("0"),
                )]),
            );
            presize_for_add_class(&mut ctx, Some(loader)).expect("upcall off");
            assert_eq!(LIST_ADDS.with(std::cell::Cell::get), 0, "no upcall: no presize");
        }
        presize_for_add_class(&mut ctx, Some(loader)).expect("ZGC");
        mock_heap_is_zgc(false);
        assert_eq!(LIST_ADDS.with(std::cell::Cell::get), 1, "ZGC: the one growth");
        let classes = loader_classes_list(&ctx, loader).expect("list");
        assert_eq!(ctx.get_field_by_name(classes, "size"), Value::Int(10));
        assert!(!array_list_is_full(&ctx, classes), "addClass now has room");
    }

    /// On the real layout `classes` is read through `ClassLoader`'s declared
    /// slot, not by name.
    #[test]
    fn zt7cl_the_list_is_read_through_the_declared_slot() {
        let mut ctx = MockNativeContext::new();
        let (loader, _) = fixture(&mut ctx, Some((0, 0)));
        assert!(!cl_has_synthetic_layout(&ctx, loader), "the fixture is the real layout");
        let index = ctx.resolve_field_index(CL_CLASS, "classes").expect("declared");
        assert_eq!(
            loader_classes_list(&ctx, loader).map(|l| Value::Object(Some(l))),
            Some(ctx.get_field(loader, index))
        );
    }

    /// The order every real-JDK door keeps: the presize before the mirror
    /// reservation, the define, then the upcall after it.
    #[test]
    fn zt7cl_every_door_presizes_before_the_reservation_and_adds_after_the_define() {
        fn body<'a>(src: &'a str, start: &str, end: &str) -> &'a str {
            let from = src.find(start).unwrap_or_else(|| panic!("{start}"));
            let to = from + src[from..].find(end).unwrap_or_else(|| panic!("{end}"));
            &src[from..to]
        }
        let lang_system = include_str!("lang_system.rs");
        let unsafe_natives = include_str!("unsafe_natives.rs");
        let lookup_define = include_str!("lookup_define.rs");
        let doors = [
            (
                body(
                    lang_system,
                    "pub(crate) fn native_classloader_define_class1(",
                    "pub(crate) fn native_classloader_define_class2(",
                ),
                "reserve_defined_class_mirror(ctx",
            ),
            (
                body(
                    lang_system,
                    "pub(crate) fn native_classloader_define_class2(",
                    "pub(crate) fn native_classloader_define_class0(",
                ),
                "reserve_defined_class_mirror(ctx",
            ),
            (
                body(
                    lang_system,
                    "pub(crate) fn native_classloader_define_class0(",
                    "pub(crate) fn native_perf_attach(",
                ),
                "reserve_mirror_for_define(ctx",
            ),
            (
                body(
                    unsafe_natives,
                    "pub(crate) fn native_unsafe_define_class(",
                    "fn native_unsafe_define_anonymous_class(",
                ),
                "reserve_mirror_for_define(",
            ),
            (
                body(lookup_define, "fn lk_define_class_b_pinned(", "\n}"),
                "reserve_mirror_for_define(ctx",
            ),
        ];
        for (i, (src, reserve)) in doors.iter().enumerate() {
            let presize = src.find("presize_for_add_class(ctx").expect("presize");
            let reserve = src.find(reserve).expect("reservation");
            let define = src.find("ctx.define_class_full(").expect("define");
            let add = src.find("add_defined_class_to_loader(ctx").expect("upcall");
            assert!(presize < reserve, "door {i}: the presize precedes the reservation");
            assert!(reserve < define && define < add, "door {i}: the upcall follows the define");
        }
    }
}
